function setup({ givenName, familyName, company, title, domain }) {
  for (const [k, v] of Object.entries({ givenName, familyName, company, title, domain }))
    if (typeof v !== "string" || !v.trim()) throw Error("Enter " + k);
  return {
    givenName: givenName.trim(),
    familyName: familyName.trim(),
    company: company.trim(),
    title: title.trim(),
    domain: domain.trim(),
    body: {
      names: [{ givenName: givenName.trim(), familyName: familyName.trim(), middleName: "" }],
    },
  };
}

return [{ json: setup({ givenName: "", familyName: "", company: "", title: "", domain: "" }) }];

function prepare({ body, resourceName, company, title, domain }) {
  if (body?.resourceName !== resourceName || !Array.isArray(body?.metadata?.sources))
    throw Error("Contact metadata missing");
  const sources = body.metadata.sources.filter(
    (s) => s?.type === "CONTACT" && typeof s.etag === "string" && s.etag,
  );
  if (sources.length !== 1) throw Error("Expected one contact source with etag");
  return {
    url: "https://people.googleapis.com/v1/" + resourceName + ":updateContact",
    body: {
      resourceName,
      metadata: { sources },
      organizations: [{ name: company, title, domain, current: true }],
    },
  };
}

const s = $("Set contact details").first().json,
  created = $("Google Contacts").first().json;
return [
  {
    json: prepare({
      body: $input.first().json,
      resourceName: created.resourceName,
      company: s.company,
      title: s.title,
      domain: s.domain,
    }),
  },
];

function confirm({ body, resourceName, company, title, domain }) {
  if (
    body?.resourceName !== resourceName ||
    !Array.isArray(body.organizations) ||
    !body.organizations.some(
      (o) => o.name === company && o.title === title && o.domain === domain && o.current === true,
    )
  )
    throw Error("Updated contact does not match");
  return { contact: body };
}

const s = $("Set contact details").first().json,
  created = $("Google Contacts").first().json;
return [
  {
    json: confirm({
      body: $input.first().json,
      resourceName: created.resourceName,
      company: s.company,
      title: s.title,
      domain: s.domain,
    }).contact,
  },
];
